import sympy
from sympy import ZZ, QQ, Symbol, Poly, minpoly, Rational

CONDITION_LABELS = [
    "H_1: alpha is an element of E",
    "H_2: alpha is algebraic over F",
    "¬Q: The kernel is not a non-zero principal ideal generated by a unique monic irreducible polynomial over F"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    try:
        F, E, alpha = witness
    except Exception:
        return [False, False, False]
        
    try:
        h1 = alpha in E
    except Exception:
        h1 = False
        
    try:
        x = Symbol('x')
        p = minpoly(alpha, x, domain=QQ)
        h2 = p is not None and p != 0
    except Exception:
        h2 = False
        
    try:
        x = Symbol('x')
        p = minpoly(alpha, x, domain=QQ)
        if p is None or p == 0:
            neg_q = False
        else:
            if F == ZZ:
                p_poly = Poly(p, x)
                _, p_Z = p_poly.clear_denoms()
                _, p_Z_prim = p_Z.primitive()
                is_monic = abs(p_Z_prim.LC()) == 1
                neg_q = not is_monic
            elif F == QQ:
                neg_q = False
            else:
                neg_q = False
    except Exception:
        neg_q = False
        
    return [bool(h1), bool(h2), bool(neg_q)]